/** What the checks make of a case: correct, or which way they fail. */
function outcome(c: Case): { ok: boolean; got: string } {
  const [side, situation, raw, reply, expect] = c
  const r = checkRephrase({ input: protect(raw), raw, output: { ok: true, reply }, side, situation, address: 'sir' })
  const blocked = r.status === 'blocked' || r.status === 'unclear'
  const w = r.warnings.map((x) => x.code).filter((x) => x !== 'order_changed')
  const got = blocked ? `blocked(${r.flags.at(-1)})` : `${r.status}${w.length ? `+${w.join(',')}` : ''}`
  if (expect === 'block') return { ok: blocked, got }
  if (blocked) return { ok: false, got }
  if (expect === 'warn:pay') return { ok: w.includes('pay_before_verification') && !w.includes('release_promise'), got }
  if (expect === 'warn:release') return { ok: w.includes('release_promise') && !w.includes('pay_before_verification'), got }
  return { ok: w.length === 0, got }
}

/** Cases the checks get wrong today, by "typed → reply". Rewrites here are left to the second check (or fail safe). */
const KNOWN = new Set<string>([
  // Dangerous, but beyond what patterns can read: the order of steps turned round, a condition made a fact, an instruction
  // or a fact taken from nowhere. The second check is there for these.
  'kyc ke baad payment karna → Sir, please make the payment first, and then complete your KYC.',
  'kyc ke baad payment karna → Sir, please make the payment now, then share your KYC.',
  'kyc ke baad hi pay karna → Sir, please pay once you are ready, and complete the KYC.',
  'payment ke baad hi mark as paid karna → Sir, please mark the order as paid and then make the payment.',
  'release payment confirm hone ke baad → Sir, we will confirm the payment after the release.',
  'agar payment fail hua to refund hoga → Sir, the payment failed; once confirmed, a refund will be issued.',
  'pls wait → Sir, please wait, then pay to the account you mentioned earlier.',
  'pls wait → Sir, please wait. As requested by our admin, kindly pay the security deposit too.',
  'pls wait → Sir, please wait. Our new UPI ID is shown in our profile; pay there.',
  'pls wait → Sir, please wait. Phir aap bhej dijiye.',
  'pls wait → Sir, please wait. Your order is approved and the USDT is reserved.',
  // Faithful, held back (fails safe): the operator sends their own words. Devanagari typed words cannot be read by the
  // typed-side checks; "11 baje" made "11 AM" is a guess at the half of the day; fractions of an hour in words.
  'पेमेंट अभी मत करना → Sir, please do not make the payment yet.',
  'पेमेंट आ गया, रिलीज़ कर रहे हैं → Sir, the payment has been received; we are releasing the USDT.',
  'kal 11 baje tak pay karna → Sir, please pay by 11 AM tomorrow.',
  'sawa ghanta lagega → Sir, it will take about an hour and a quarter.',
  'payment 15 min me → Sir, please pay within a quarter of an hour.',
])

const key = (c: Case) => `${c[2]} → ${c[3]}`
for (const [kind, groups] of [['held back', ADV], ['offered', OK]] as const) {
  for (const [group, cases] of Object.entries(groups)) {
    Deno.test(`review: ${group} (${kind})`, () => {
      const wrong: string[] = [], fixed: string[] = []
      for (const c of cases) {
        const o = outcome(c)
        if (KNOWN.has(key(c))) { if (o.ok) fixed.push(key(c)) } else if (!o.ok) wrong.push(`${key(c)}  [expected ${c[4]}, got ${o.got}]`)
      }
      if (wrong.length || fixed.length) {
        throw new Error([...wrong.map((x) => `wrong: ${x}`), ...fixed.map((x) => `now right, take it off KNOWN: ${x}`)].join('\n'))
      }
    })
  }
}
